-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhCN" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.warlock.dps.Name"] = "所有天赋树"
L["rm.era.warlock.dps.Description"] = "1–60 级，所有天赋树，也适用于专家模式和自给自足服务器；综合 Wowhead、Icy Veins、Warcraft Tavern 和 模拟器。你施法或引导时会暂停，单刷时绝不抢别人正在攻击的怪物。夜幕的暗影冥思优先；组队目标用暗影灼烧和灼热之痛收尾；单刷时即将死亡的目标使用吸取灵魂（为了获取碎片，或拥有强化吸取灵魂时）、暗影灼烧或燃烧，然后是魔杖，绝不施放新的持续伤害效果。移动时只使用瞬发法术。三个或更多敌人时：敌人在你身边且你的生命值还有一半时使用地狱烈焰，否则使用火焰之雨。一个诅咒：团队副本中没人施放时使用暗影诅咒或元素诅咒，长时间的精英战斗使用厄运诅咒，否则使用痛苦诅咒。献祭在划算时使用（毁灭、团队副本或法力值有 40% 时），腐蚀术，生命虹吸（团队副本中仅在有暗影易伤时）。单刷时：黑暗契约，生命值充足时使用生命分流，受伤时使用吸取生命，魔杖。否则使用暗影箭。提醒：魔甲术或恶魔皮肤、你的宠物（单刷用虚空行者，组队用小鬼，恶魔牺牲用魅魔）、恶魔支配、恶魔牺牲、诅咒增幅，生命值低时使用虚空行者的牺牲和治疗石，生命通道。诅咒分配、对逃跑的怪物使用鲁莽诅咒、恐惧术、放逐术、灵魂石和制造治疗石由你自己掌控。"
L["rm.era.warlock.dps.icyveins.Name"] = "诅咒和腐蚀术团队（Icy Veins）"
L["rm.era.warlock.dps.icyveins.Description"] = "Icy Veins 针对有 16 个减益效果上限的服务器的列表，是推荐的术士内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。团队副本中只用你的诅咒和腐蚀术，然后是暗影箭，不用献祭也不用生命虹吸。升级和地下城与推荐的内置循环相同。"
L["rm.era.warlock.dps.warcrafttavern.Name"] = "吸血坦（Warcraft Tavern）"
L["rm.era.warlock.dps.warcrafttavern.Description"] = "Warcraft Tavern 的升级打法，是推荐的术士内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。先用小鬼，20 级起用魅魔。献祭、生命虹吸和腐蚀术，然后在学会第四级吸取生命后，单刷时以吸取生命作为填充（学会前用魔杖），生命值接近满时使用生命分流，宠物法力未满前使用黑暗契约。团队副本中施放栏位允许的所有持续伤害效果，然后是暗影箭。收尾、诅咒和安全提醒与推荐的内置循环相同；恐惧第二个怪物由你自己掌控。"
L["rm.forever.warlock.dps.Name"] = "所有天赋树"
L["rm.forever.warlock.dps.Description"] = "适用于 1 至 60 级的所有术士天赋树，综合 Icy Veins、Wowhead 和 Method；某个天赋树的步骤会在你学会它的天赋法术后出现。以献祭和痛苦灾祸拉怪（毁灭预读暗影箭），利用夜幕和灭杀的触发，以灼热之痛保持恶魔印记。移动时只施放瞬发法术。怪群时：组队时地狱烈焰、火焰之雨、腐蚀术和痛苦灾祸。然后对精英和首领使用末日灾祸，否则使用痛苦灾祸，组队时和对精英使用元素诅咒，献祭、腐蚀术、生命虹吸、燃烧和暗影灼烧；单刷时以折磨、吸取生命（需有吸取天赋）或魔杖填充；否则使用烧尽或暗影箭。提醒：护甲、一个恶魔（魅魔，否则虚空行者，再否则小鬼）、恶魔支配、配合恶魔契约的恶魔牺牲、灵魂链接、武器石、诅咒增幅以及对第二个敌人使用浩劫灾祸。由你自己掌控：派宠物攻击、其他诅咒、恐惧术、治疗石和其他目标。在永久服上生命值和法力值对插件隐藏，因此斩杀阶段（吸取灵魂、以暗影灼烧作最后一击）、生命分流、生命通道和受伤时吸取由你自己决定。"
L["rm.forever.warlock.dps.icyveins.Name"] = "所有天赋树（Icy Veins）"
L["rm.forever.warlock.dps.icyveins.Description"] = "Icy Veins 的术士升级打法：魔杖是单刷时的填充，虚空行者是默认恶魔，痛苦和毁灭会牺牲恶魔并在没有恶魔的情况下作战（分别从 41 级和 55 级起），恶魔学识保持恶魔印记，并且只把献祭作为填充，毁灭在学会烧尽后，会对怪群中最耐打的敌人施放浩劫灾祸，并在冷却完毕时使用燃烧。如果你遵循 Icy Veins，请选择它而不是推荐的术士内置循环。在永久服上生命值、法力值和死亡倒计时对插件隐藏，因此受伤时的吸取生命、生命分流以及哪些目标能存活足够久来吃持续伤害，都由你自己决定。它是推荐的术士 DPS 内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。"
L["rm.forever.warlock.dps.wowhead.Name"] = "所有天赋树（Wowhead）"
L["rm.forever.warlock.dps.wowhead.Description"] = "Wowhead 的 30 级术士：痛苦和恶魔学识带着魅魔进行吸血坦打法（腐蚀术和痛苦灾祸，不用献祭，然后在剩余战斗中使用吸取生命；永久服中生命值和法力值是隐藏的，因此生命分流由你自己决定），恶魔学识保持恶魔印记，且只对高血量目标施放痛苦灾祸，毁灭对每个怪物施放痛苦灾祸、腐蚀术和献祭，在献祭结束前使用燃烧，把暗影灼烧留作最后一击，并带着虚空行者使用魔杖。诅咒增幅每次冷却完毕即用；元素诅咒和末日灾祸仅用于精英和首领；没有怪群部分。Wowhead 的指南只写到 30 级。它是推荐的术士 DPS 内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。"
L["rm.mop.warlock.affliction.Name"] = "推荐"
L["rm.mop.warlock.affliction.Description"] = "推荐痛苦专精使用，适用于 10 至 90 级（在痛苦专精中选用）。预读鬼影缠身或痛苦无常，对新的精英以灵魂燃烧和灵魂交换开场，保持痛楚、腐蚀术和痛苦无常（黑暗灵魂：哀难期间提前刷新），鬼影缠身即将结束且你有两块灵魂碎片时（或黑暗灵魂期间）施放鬼影缠身，鬼影缠身即将结束而你没有灵魂碎片时引导吸取灵魂获取碎片，低于 20% 时使用吸取灵魂，否则使用灾难之握（42 级前为暗影箭）。三个或更多敌人时使用腐蚀之种（六个时配合灵魂燃烧）。移动时：瞬发法术和邪焰。提醒：你的宠物、黑暗意图、组队时使用元素诅咒、黑暗灵魂、末日守卫或地狱火、魔典：邪恶仆从或魔典：恶魔牺牲、生命分流、防御技能。由你自己掌控：把持续伤害效果扩散到其他目标，以及在它们之间用灵魂交换转移。"
L["rm.mop.warlock.affliction.warcrafttavern.Name"] = "攒碎片放鬼影缠身（Warcraft Tavern）"
L["rm.mop.warlock.affliction.warcrafttavern.Description"] = "默认关闭。Warcraft Tavern 和 Method 的灵魂碎片策略：持续伤害效果的维持与推荐的痛苦内置循环相同，但鬼影缠身会留到四块灵魂碎片或黑暗灵魂：哀难时，低于 20% 时只要有一块灵魂碎片就用灵魂燃烧和灵魂交换刷新所有持续伤害效果。启用它并禁用推荐的痛苦内置循环即可使用。"
L["rm.mop.warlock.demonology.Name"] = "推荐"
L["rm.mop.warlock.demonology.Description"] = "推荐恶魔学识专精使用，适用于 10 至 90 级（在恶魔学识专精中选用）。施法者形态下：腐蚀术，按充能使用古尔丹之手，单层暗影烈焰即将消失时用第二个古尔丹之手接恶魔变形，黑暗灵魂：学识期间（或恶魔之怒接近满时）使用恶魔变形，熔火之心达到两层或低于 25% 时使用灵魂之火，四个或更多敌人时使用地狱烈焰，暗影箭。恶魔变形期间：末日降临，用混乱之触保持腐蚀术，熔火之心触发时使用灵魂之火，对怪群使用献祭光环或虚空射线，混乱之触，并在黑暗灵魂未生效且恶魔之怒不高于 300 时提示你退出恶魔变形。提醒：恶魔卫士（或愤怒卫士）、黑暗意图、黑暗灵魂、小鬼成群、魔典：恶魔卫士、末日守卫或地狱火、生命分流、单刷时使用生命通道。由你自己掌控：魔刃风暴（宠物自动施放）和恶魔飞跃。"
L["rm.mop.warlock.demonology.guide.Name"] = "攒熔火之心（指南）"
L["rm.mop.warlock.demonology.guide.Description"] = "默认关闭。指南的共识（Method、wowtbc.gg、Warcraft Tavern、Wowhead）：与推荐的恶魔学识内置循环相同，只是施法者形态下恶魔变形会等到 900 点恶魔之怒或黑暗灵魂，灵魂之火只在熔火之心达到八层或低于 25% 时施放，因此层数会在恶魔形态下消耗。启用它并禁用推荐的恶魔学识内置循环即可使用。"
L["rm.mop.warlock.destruction.Name"] = "推荐"
L["rm.mop.warlock.destruction.Description"] = "适用于毁灭专精，10 至 90 级（在毁灭专精中选用）。预读烧尽，保持献祭，绝不让燃烧积压两层充能，在 3.5 块爆燃灰烬时或黑暗灵魂：易爆期间把爆燃灰烬花在混乱之箭上（低于 20% 时用暗影灼烧），爆燃用于烧尽，并以烧尽作为填充；濒死的目标使用暗影灼烧。三个或更多敌人时：火焰之雨，四个时使用硫磺烈火，然后是献祭、燃烧和烧尽，并在你的爆燃灰烬耗尽时提示关闭硫磺烈火。移动时：暗影灼烧、燃烧、邪焰。提醒：你的宠物或魔典：恶魔牺牲、克索诺斯之焰、黑暗意图、黑暗灵魂、两个或更多敌人时使用浩劫（请自行对第二个目标施放）、末日守卫或地狱火、灰烬转换和防御技能。"
L["rm.mop.warlock.unspecialized.Name"] = "无专精"
L["rm.mop.warlock.unspecialized.Description"] = "适用于没有专精的术士（1 至 9 级，或之后选择专精之前）。用腐蚀术拉怪并保持它，生命值低于一半时使用吸取生命，暗影箭。提醒：单刷时召唤虚空行者（组队时召唤小鬼），以及拉怪间隙的治疗石。"
L["rm.retail.warlock.affliction.Name"] = "暴雪战斗辅助"
L["rm.retail.warlock.affliction.Description"] = "推荐至暗之夜的痛苦专精使用。在战斗中，游戏现在会对插件隐藏你的持续伤害效果、触发效果、冷却时间和生命值，因此它会显示暴雪自己的战斗辅助建议（一键循环，它会维持痛楚和腐蚀术、把灵魂碎片花在痛苦无常上，并处理牺牲魔典），并在你施法、引导或没有选中敌人时停止。提醒它未包含的内容：战斗中的召唤黑眼、拉怪间隙召唤地狱猎犬（除非你已牺牲了恶魔）、对可打断的施法使用恶魔掌控（只在游戏允许读取该施法的场合亮起）、战斗中一就绪就使用的黑暗契约和不灭决心（生命值在正式服中是隐藏的，因此何时使用由你自己决定）。"
L["rm.retail.warlock.affliction.icyveins.Name"] = "参考（Icy Veins）"
L["rm.retail.warlock.affliction.icyveins.Description"] = "仅供参考，默认关闭：Icy Veins 和 SimulationCraft（灵魂收割者）的施放顺序需要读取持续伤害效果的计时、夜幕和碎片动荡，而至暗之夜会在战斗中隐藏它们。拉怪前使用鬼影缠身；面对三个或更多交战中的敌人且没有你的腐蚀术时使用腐蚀之种；鬼影缠身；痛楚以及腐蚀术或枯萎剩余不足 3 秒时刷新；灵魂碎片不超过两个时使用幽冥收割；5 个灵魂碎片时使用痛苦无常；两层夜幕时使用灾难之握，否则使用暗影箭；碎片动荡触发或 4 个灵魂碎片时使用痛苦无常；吸取灵魂；暗影箭。提醒：幽冥收割进入冷却后使用召唤黑眼、怨毒、召唤地狱猎犬，以及通用提醒。"
L["rm.retail.warlock.demonology.Name"] = "暴雪战斗辅助"
L["rm.retail.warlock.demonology.Description"] = "推荐至暗之夜的恶魔学识专精使用。显示暴雪的战斗辅助建议（召唤恐惧猎犬、古尔丹之手、恶魔之箭、能量虹吸和恶魔暴君），并在你施法、引导或没有选中敌人时停止。提醒它未包含的内容：你在最近 12 秒内召唤的恐惧猎犬仍在场时使用召唤恶魔暴君、战斗中的魔典：小鬼领主、魔典：邪能破坏者和召唤末日守卫、拉怪间隙召唤恶魔卫士、恶魔掌控、黑暗契约、不灭决心。"
L["rm.retail.warlock.demonology.icyveins.Name"] = "参考（Icy Veins）"
L["rm.retail.warlock.demonology.icyveins.Description"] = "仅供参考，默认关闭：Icy Veins 和 SimulationCraft（恶魔使徒）的施放顺序需要读取恶魔之核、小鬼数量和冷却计时，而至暗之夜会在战斗中隐藏它们。拉怪前使用能量虹吸、恶魔之箭和暗影箭；然后恶魔之核不超过一层时使用能量虹吸，魔典：小鬼领主，魔典：邪能破坏者，召唤末日守卫，召唤恐惧猎犬，5 个灵魂碎片时使用召唤恶魔暴君，面对三个或更多交战中的敌人时使用内爆，陨灭，3 个或更多灵魂碎片时使用古尔丹之手，少于 3 个时使用狱火箭，恶魔之核触发且灵魂碎片少于 4 个时使用恶魔之箭，暗影箭。"
L["rm.retail.warlock.destruction.Name"] = "暴雪战斗辅助"
L["rm.retail.warlock.destruction.Description"] = "推荐至暗之夜的毁灭专精使用。显示暴雪的战斗辅助建议（献祭或枯萎、燃烧、混乱之箭、火焰之雨、灵魂之火、怨毒），并在你施法、引导或没有选中敌人时停止。提醒它未包含的内容：战斗中的召唤地狱火、拉怪间隙召唤小鬼（除非你已牺牲了恶魔）、恶魔掌控、黑暗契约、不灭决心。对第二个目标使用浩劫仍由你自己掌控。"
L["rm.retail.warlock.destruction.icyveins.Name"] = "溢出前使用混乱之箭参考（Icy Veins）"
L["rm.retail.warlock.destruction.icyveins.Description"] = "仅供参考，默认关闭：Icy Veins 的地狱召唤者施放顺序，会在灵魂碎片溢出前把它们花在混乱之箭上，并在冷却好时就使用暗影灼烧和引导恶魔之火。面对三个或更多交战中的敌人时使用火焰之雨；保持枯萎或献祭；召唤地狱火；怨毒；暗影灼烧；灵魂碎片少于 4 个时使用灵魂之火；4 个或更多时使用混乱之箭；大灾变；少于 4 个时使用狱火箭；引导恶魔之火；燃烧；烧尽。"
L["rm.retail.warlock.destruction.simc.Name"] = "参考（SimulationCraft）"
L["rm.retail.warlock.destruction.simc.Description"] = "仅供参考，默认关闭：SimulationCraft 的施放顺序需要读取献祭、爆燃、充能和冷却计时，而至暗之夜会在战斗中隐藏它们。拉怪前使用灵魂之火和烧尽；面对三个或更多交战中的敌人时，3 个灵魂碎片时使用火焰之雨，并使用大灾变；然后灵魂碎片不超过 4 个时使用灵魂之火，仅在 5 个时使用混乱之箭，两层充能时或灵魂碎片少于 4 个且没有爆燃时使用燃烧，召唤地狱火，怨毒，枯萎或献祭剩余最后 30% 时刷新，陨灭，大灾变，灵魂碎片不超过 3 个时使用狱火箭，烧尽。"
L["rm.retail.warlock.initial.Name"] = "暴雪战斗辅助"
L["rm.retail.warlock.initial.Description"] = "推荐在你选择专精之前使用（此时游戏报告的是术士的初始专精）。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时包含所有术士内置循环共用的提醒，每一项在你学会对应法术后生效。当你在 10 级选择专精后，该专精的内置循环会接管。"
L["rm.sod.warlock.fire.Name"] = "火焰（探索赛季）"
L["rm.sod.warlock.fire.Description"] = "探索赛季的毁灭，铭刻了混乱之箭或烧尽后选用；综合 模拟器 第 6 阶段和 Wowhead。用暗影灼烧和灼热之痛收尾；移动时使用瞬发法术；烧尽的增益效果，对怪群使用火焰之湖和地狱烈焰；一个诅咒（组队时没人施放则用鲁莽诅咒，长时间的精英战斗用厄运诅咒，否则用痛苦诅咒）；燃烧仅用于保持爆燃；保持献祭和烧尽的增益效果；低于 35% 时在灭杀期间用灵魂之火代替混乱之箭；灵魂之火！触发；混乱之箭；单刷时使用引导大师的吸取生命和生命分流；烧尽（铭刻前为暗影箭）。提醒：邪甲术、小鬼、诅咒增幅以及安全提醒。"
L["rm.sod.warlock.fire.icyveins.Name"] = "火焰，燃烧冷却完毕即用（探索赛季，Icy Veins）"
L["rm.sod.warlock.fire.icyveins.Description"] = "Icy Veins 和 Warcraft Tavern 的探索赛季毁灭，是推荐的探索赛季火焰内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。保持献祭，燃烧和混乱之箭冷却完毕即用（低于 35% 时也使用混乱之箭），烧尽的增益效果，低于 35% 时在灭杀期间使用灵魂之火，烧尽作为填充；伤害型诅咒仅在移动时使用，组队时没人施放则用鲁莽诅咒。"
L["rm.sod.warlock.shadow.Name"] = "暗影（探索赛季，痛苦、恶魔卫士）"
L["rm.sod.warlock.shadow.Description"] = "探索赛季的痛苦和恶魔卫士天赋，也是没有其他内置循环适用时所有探索赛季术士的默认循环；综合 模拟器 第 6 阶段、Wowhead 和 Icy Veins。夜幕触发；组队目标用暗影灼烧或吸取灵魂收尾；单刷时濒死的目标使用吸取灵魂，而不是持续伤害效果；移动时使用瞬发法术；对怪群使用火焰之湖和地狱烈焰；一个诅咒（组队时没人施放则用鲁莽诅咒，否则用痛苦诅咒）；痛苦无常，引导大师的吸取生命，暗影烈焰（铭刻前为献祭），腐蚀术，鬼影缠身，生命虹吸（铭刻了祈求时各自在剩余不足 6 秒时续上）；铭刻灵魂虹吸后低于 20% 时使用吸取灵魂；单刷续航和魔杖；暗影箭。提醒：邪甲术、你的宠物（铭刻后为恶魔卫士）、宠物法力不足时使用生命分流、诅咒增幅以及安全提醒。诅咒分配和对怪群使用暗影箭雨由你自己掌控。"
L["rm.sod.warlock.shadow.simulator.Name"] = "暗影，吸取灵魂填充（探索赛季，模拟器）"
L["rm.sod.warlock.shadow.simulator.Description"] = "模拟器 第 6 阶段针对灵魂虹吸天赋的痛苦列表，是推荐的探索赛季暗影内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。无论目标生命值如何，都以吸取灵魂作为填充，下一个步骤一到时机就会显示，你可以为它截断引导；其他任何引导则会让它完成。痛苦无常和暗影烈焰剩余 7.5 秒时续上，痛苦诅咒和腐蚀术剩余 6 秒时续上，引导大师的吸取生命，鬼影缠身，暗影箭仅在暗影冥思触发时使用，生命虹吸，法力值低于 10% 时使用生命分流。提醒与推荐的内置循环相同。"
L["rm.sod.warlock.tank.Name"] = "坦克（探索赛季，恶魔变形）"
L["rm.sod.warlock.tank.Description"] = "探索赛季的坦克，铭刻了恶魔变形后选用；综合 模拟器、Icy Veins、Wowhead 和 Warcraft Tavern。防御者的决心缺失或即将结束时使用暗影顺劈，灵魂之火！触发，用烧尽保持其火焰增益；三个或更多敌人时使用暗影顺劈、火焰之湖、暗影烈焰和地狱烈焰。然后是一个诅咒（痛苦诅咒，没人施放时改用鲁莽诅咒），暗影烈焰（铭刻前为献祭），引导大师的吸取生命，腐蚀术，生命虹吸，为爆燃使用燃烧，低于 35% 时在灭杀期间使用灵魂之火，并以灼热之痛作为仇恨填充。提醒：恶魔变形、邪甲术、你的宠物、献祭光环、恶魔优雅、生命值低时使用复仇、目标攻击其他人时使用威吓、对怪群使用恶魔嚎叫、诅咒增幅、宠物法力不足时使用生命分流。地狱火护甲由你自己掌控。"
L["rm.tbc.warlock.dps.icyveins.Name"] = "所有天赋树（Icy Veins）"
L["rm.tbc.warlock.dps.icyveins.Description"] = "1 至 70 级的所有天赋树。诅咒，然后随着学会依次加入痛苦无常、献祭、腐蚀术和生命虹吸，暗影箭或烧尽；夜幕和反冲触发优先；三个或更多敌人时使用腐蚀之种、地狱烈焰和暗影之怒。单刷时受伤会吸取生命，会使用生命分流和魔杖，并对濒死目标使用吸取灵魂或收尾法术。提醒：邪甲术、魔甲术或恶魔皮肤、你的恶魔、恶魔牺牲、灵魂链接、诅咒增幅和灵魂碎裂。恐惧和其他诅咒由你自己掌控。"
L["rm.tbc.warlock.dps.wowhead.Name"] = "吸血坦（Wowhead）"
L["rm.tbc.warlock.dps.wowhead.Description"] = "依据 Wowhead 指南的术士，是推荐的 Icy Veins 术士内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。单刷时采用吸血坦打法：持续伤害效果都上齐后以吸取生命作为填充，献祭和生命虹吸留给精英怪。组队时总是施放献祭，排在腐蚀术和生命虹吸之后。其余与推荐的内置循环相同。"
